mapper.insert:
INSERT INTO promotion_boost_campaign (
    id, creator_user_id, post_id, channel, bid_amount, boost_value, unit_price, budget_total, budget_consumed,
    reserve_business_ref, status, start_at, end_at, closed_at, created_at, updated_at
) VALUES (
    #{id}, #{creatorUserId}, #{postId}, #{channel}, #{bidAmount}, #{boostValue}, #{unitPrice}, #{budgetTotal}, #{budgetConsumed},
    #{reserveBusinessRef}, #{status}, #{startAt}, #{endAt}, #{closedAt}, #{createdAt}, #{updatedAt}
)

mapper.select:
SELECT *
FROM promotion_boost_campaign
WHERE channel = #{channel}
  AND status = 'ACTIVE'
  AND start_at <= #{now}
  AND end_at > #{now}
  AND budget_consumed < budget_total
ORDER BY boost_value DESC, id ASC

SELECT *
FROM promotion_boost_campaign
WHERE status = 'ACTIVE'
  AND end_at <= #{now}
ORDER BY end_at ASC, id ASC
LIMIT #{limit}

mapper.update:
UPDATE promotion_boost_campaign
SET budget_consumed = budget_consumed + #{amount},
    updated_at = #{updatedAt}
WHERE id = #{id}

UPDATE promotion_boost_campaign
SET status = 'CLOSED',
    closed_at = #{closedAt},
    updated_at = #{updatedAt}
WHERE id = #{id}
